#define ECCref_MAX_BITS  512
#define ECCref_MAX_LEN   ((ECCref_MAX_BITS + 7) / 8)     /* = 64 */

typedef struct ECCrefPublicKey_st {
    unsigned int  bits;                    /* SM2 填 256 */
    unsigned char x[ECCref_MAX_LEN];       /* 64 字节，有效数据在 [32..63] */
    unsigned char y[ECCref_MAX_LEN];
} ECCrefPublicKey;

typedef struct ECCrefPrivateKey_st {
    unsigned int  bits;
    unsigned char D[ECCref_MAX_LEN];       /* 字段名是大写 D */
} ECCrefPrivateKey;

typedef struct ECCSignature_st {
    unsigned char r[ECCref_MAX_LEN];       /* 64，SM2 用后 32 */
    unsigned char s[ECCref_MAX_LEN];
} ECCSignature;                            /* 注意：没有 bits 字段 */

#define ECCref_MAX_CIPHER_LEN  136         /* 定义了，但结构体里没用它，见下 */

typedef struct ECCCipher_st {
    unsigned char x[ECCref_MAX_LEN];       /* 64  → C1 的 x */
    unsigned char y[ECCref_MAX_LEN];       /* 64  → C1 的 y */
    unsigned char M[32];                   /* 32  → C3（SM3 摘要） */
    unsigned int  L;                       /* 密文 C 的实际有效长度 */
    unsigned char C[136];                  /* 136 → C2，定长数组（字面量，非宏） */
} ECCCipher;

typedef struct ecccipherblob_st {
    unsigned char XCoordinate[64];
    unsigned char YCoordinate[64];
    unsigned char Hash[32];
    unsigned int  CipherLen;
    unsigned char Cipher[128];      /* ← 128，不是 136！ */
} ECCCIPHERBLOB, *PECCCIPHERBLOB;

typedef struct SDF_ENVELOPEDKEYBLOB {
    unsigned long     ulAsymmAlgID;         /* ← unsigned long */
    unsigned long     ulSymmAlgID;          /* ← unsigned long */
    ECCCIPHERBLOB     ECCCipherBlob;
    ECCPUBLICKEYBLOB  PubKey;
    unsigned char     cbEncryptedPrikey[64];
} ENVELOPEDKEYBLOB, *PENVELOPEDKEYBLOB;

typedef struct DeviceInfo_st {
    unsigned char IssuerName[40];      /* 厂商名 */
    unsigned char DeviceName[16];      /* 型号 */
    unsigned char DeviceSerial[16];    /* 编号：日期(8)+批次(3)+流水(5) */
    unsigned int  DeviceVersion;
    unsigned int  StandardVersion;
    unsigned int  AsymAlgAbility[2];   /* [0]=支持的非对称算法位或；[1]=最大模长位或 */
    unsigned int  SymAlgAbility;       /* 支持的对称算法位或 */
    unsigned int  HashAlgAbility;      /* 支持的杂凑算法位或 */
    unsigned int  BufferSize;          /* 最大文件存储空间（字节） */
} DEVICEINFO;

#define RSAref_MAX_BITS   2048                        /* ← 上限就是 2048 */
#define RSAref_MAX_LEN    ((RSAref_MAX_BITS + 7) / 8) /* = 256 */
#define RSAref_MAX_PLEN   128

typedef struct RSArefPublicKey_st {
    unsigned int  bits;
    unsigned char m[256];      /* 模 N */
    unsigned char e[256];      /* 公钥指数 */
} RSArefPublicKey;

typedef struct RSArefPrivateKey_st {
    unsigned int  bits;
    unsigned char m[256], e[256], d[256];
    unsigned char prime[2][128];   /* p, q —— 二维数组 */
    unsigned char pexp[2][128];    /* dP, dQ */
    unsigned char coef[128];       /* qInv */
} RSArefPrivateKey;
